find:
{daysToDeadline !== null && (
  <span className="inline-flex items-center gap-1 bg-foreground text-primary text-[11px] font-bold px-2.5 py-1 rounded-full">
    <Clock className="h-3 w-3" />
    {daysToDeadline === 0
      ? "Booking closes today"
      : daysToDeadline === 1
      ? "Booking closes tomorrow"
      : `Booking closes in ${daysToDeadline} days`}
  </span>
)}

replace:
  "Returning Klovers students: a discount on your next enrollment, and extra savings when friends join.",
canonical: PAGE_URL,
// 25 Sep 2026 (QA): the page shows the returning-student promo code, so
// it is kept out of search results and out of sitemap.xml.
noindex: true,

find:
{idx === activeLevel && (
  <span className="text-[10px] bg-klovers-yellow text-charcoal px-2 py-0.5 rounded-full font-medium animate-pulse border border-charcoal/10">
    {t("placementCta.detecting")}
  </span>
)}

replace:
{idx === activeLevel && idx < LEVELS.length - 1 && (
  <span className="text-[10px] bg-klovers-yellow text-charcoal px-2 py-0.5 rounded-full font-medium animate-pulse border border-charcoal/10">
    {t("placementCta.detecting")}
  </span>
)}
